def ensure_cf_attrs(ds):
    ds["longitude"].attrs.update({
        "standard_name": "longitude",
        "units": "degrees_east"
    })
    ds["latitude"].attrs.update({
        "standard_name": "latitude",
        "units": "degrees_north"
    })
    return ds

